//
//  WordTranslationService.swift
//  SwiftMandarin
//
//  Service for translating individual words/phrases using Apple's Translation
//  API (iOS 18+/macOS 15+). On older systems it falls back to the configured
//  AI provider, so word lookups keep working on iOS 17.
//

import Foundation
import Translation

/// Service for translating individual words using Apple's Translation API
@Observable
final class WordTranslationService {

    static let shared = WordTranslationService()

    /// Cache for translated words to avoid repeated API calls
    private var translationCache: [String: String] = [:]

    private init() {}

    // MARK: - Public Methods

    /// Translate a single word or phrase from Chinese to English
    /// Uses installed language packs (requires languages to be pre-downloaded)
    /// - Parameter word: The Chinese word/phrase to translate
    /// - Returns: The English translation
    func translateToEnglish(_ word: String) async throws -> String {
        // Check cache first
        let cacheKey = "zh-en:\(word)"
        if let cached = translationCache[cacheKey] {
            return cached
        }

        let translation = try await systemOrAITranslate(word, sourceIsChinese: true)
        translationCache[cacheKey] = translation
        return translation
    }

    /// Translate a single word or phrase from English to Chinese
    /// Uses installed language packs (requires languages to be pre-downloaded)
    /// - Parameter word: The English word/phrase to translate
    /// - Returns: The Chinese translation
    func translateToChinese(_ word: String) async throws -> String {
        // Check cache first
        let cacheKey = "en-zh:\(word)"
        if let cached = translationCache[cacheKey] {
            return cached
        }

        let translation = try await systemOrAITranslate(word, sourceIsChinese: false)
        translationCache[cacheKey] = translation
        return translation
    }

    /// Translate a word with automatic language detection
    /// - Parameters:
    ///   - word: The word to translate
    ///   - sourceIsChinese: Whether the source word is Chinese
    /// - Returns: The translated word in the opposite language
    func translate(_ word: String, sourceIsChinese: Bool) async throws -> String {
        if sourceIsChinese {
            return try await translateToEnglish(word)
        } else {
            return try await translateToChinese(word)
        }
    }

    /// Batch translate multiple words (more efficient for multiple lookups)
    /// - Parameters:
    ///   - words: Array of words to translate
    ///   - sourceIsChinese: Whether source words are Chinese
    /// - Returns: Dictionary mapping original words to translations
    func translateBatch(_ words: [String], sourceIsChinese: Bool) async throws -> [String: String] {
        var results: [String: String] = [:]
        var wordsToTranslate: [String] = []

        // Check cache first
        let cachePrefix = sourceIsChinese ? "zh-en:" : "en-zh:"
        for word in words {
            let cacheKey = "\(cachePrefix)\(word)"
            if let cached = translationCache[cacheKey] {
                results[word] = cached
            } else {
                wordsToTranslate.append(word)
            }
        }

        // Return early if all words were cached
        if wordsToTranslate.isEmpty {
            return results
        }

        if #available(iOS 26.0, macOS 26.0, *) {
            // Create translation session using installed languages
            let session = TranslationSession(
                installedSource: sourceIsChinese ? Locale.Language(identifier: "zh-Hans") : Locale.Language(identifier: "en"),
                target: sourceIsChinese ? Locale.Language(identifier: "en") : Locale.Language(identifier: "zh-Hans")
            )

            // Create batch requests with client identifiers for matching
            var requests: [TranslationSession.Request] = []
            for (index, word) in wordsToTranslate.enumerated() {
                requests.append(TranslationSession.Request(
                    sourceText: word,
                    clientIdentifier: "\(index)"
                ))
            }

            // Perform batch translation
            let responses = try await session.translations(from: requests)

            // Process responses and update cache
            for response in responses {
                if let clientId = response.clientIdentifier,
                   let index = Int(clientId),
                   index < wordsToTranslate.count {
                    let originalWord = wordsToTranslate[index]
                    let translation = response.targetText

                    results[originalWord] = translation
                    translationCache["\(cachePrefix)\(originalWord)"] = translation
                }
            }
        } else {
            // Pre-iOS 26: translate sequentially through the configured AI
            // provider (each result is cached, so repeat lookups are free).
            for word in wordsToTranslate {
                let translation = try await AIWordExplanationService.shared
                    .translateWithProvider(word, sourceIsChinese: sourceIsChinese)
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                guard !translation.isEmpty else { continue }
                results[word] = translation
                translationCache["\(cachePrefix)\(word)"] = translation
            }
        }

        return results
    }

    /// Clear the translation cache
    func clearCache() {
        translationCache.removeAll()
    }

    /// Get cached translation if available
    func getCachedTranslation(for word: String, sourceIsChinese: Bool) -> String? {
        let cacheKey = sourceIsChinese ? "zh-en:\(word)" : "en-zh:\(word)"
        return translationCache[cacheKey]
    }

    // MARK: - Backend Selection

    /// Apple's on-device Translation API where available (iOS 26+/macOS 26+;
    /// the standalone session initializer is newer than the SwiftUI task API),
    /// otherwise the user's configured AI provider.
    private func systemOrAITranslate(_ text: String, sourceIsChinese: Bool) async throws -> String {
        if #available(iOS 26.0, macOS 26.0, *) {
            let session = TranslationSession(
                installedSource: Locale.Language(identifier: sourceIsChinese ? "zh-Hans" : "en"),
                target: Locale.Language(identifier: sourceIsChinese ? "en" : "zh-Hans")
            )
            let response = try await session.translate(text)
            return response.targetText
        } else {
            return try await AIWordExplanationService.shared
                .translateWithProvider(text, sourceIsChinese: sourceIsChinese)
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }
    }
}

//
//  RubyTextView.swift
//  SwiftMandarin
//
//  Ruby text display for Chinese characters with pinyin annotations
//  Displays pinyin directly above each character/word segment
//

import SwiftUI

/// A word segment with its pinyin displayed above the character
struct RubySegment: Identifiable {
    let id = UUID()
    let text: String
    let pinyin: String
    let partOfSpeech: PartOfSpeech

    /// Translated meaning (fetched asynchronously)
    var translation: String?

    init(from analyzedWord: AnalyzedWord) {
        self.text = analyzedWord.text
        self.pinyin = PinyinConverter.convert(analyzedWord.text)
        self.partOfSpeech = analyzedWord.partOfSpeech
        self.translation = nil
    }

    /// Build a segment from an AI-identified word. The model supplies the word
    /// boundary, pinyin, part of speech, and an English meaning. Pinyin falls
    /// back to the local converter if the model omitted it; the meaning is kept
    /// in `translation` so the detail popover can show it without a re-lookup.
    init(aiWord: IdentifiedWord) {
        self.text = aiWord.word
        let trimmedPinyin = aiWord.pinyin.trimmingCharacters(in: .whitespacesAndNewlines)
        self.pinyin = trimmedPinyin.isEmpty ? PinyinConverter.convert(aiWord.word) : trimmedPinyin
        self.partOfSpeech = PartOfSpeech(aiLabel: aiWord.partOfSpeech)
        let trimmedMeaning = aiWord.meaning.trimmingCharacters(in: .whitespacesAndNewlines)
        self.translation = trimmedMeaning.isEmpty ? nil : trimmedMeaning
    }

    /// Check if segment is valid for display (has actual content)
    var isValidForDisplay: Bool {
        !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    /// Whether this segment is punctuation (should be displayed inline without ruby annotation)
    var isPunctuation: Bool {
        partOfSpeech.isPunctuation || 
        (!text.contains(where: { $0.isChineseCharacter || $0.isLetter }))
    }
}

/// Interactive ruby text view that displays Chinese characters with pinyin above
/// Tapping on a word/character shows a popup with details
struct RubyTextView: View {
    let chineseText: String
    let englishMeaning: String
    /// Pre-computed segments from the AI. When non-empty these are used
    /// verbatim (proper word boundaries, pinyin, meaning); when nil/empty the
    /// view falls back to local NLTokenizer segmentation.
    let aiSegments: [RubySegment]?
    let onWordTap: ((RubySegment) -> Void)?

    @State private var segments: [RubySegment] = []

    init(chineseText: String, englishMeaning: String = "", aiSegments: [RubySegment]? = nil, onWordTap: ((RubySegment) -> Void)? = nil) {
        self.chineseText = chineseText
        self.englishMeaning = englishMeaning
        self.aiSegments = aiSegments
        self.onWordTap = onWordTap
    }

    /// Stable, Equatable token so `onChange` re-segments when AI results arrive
    /// asynchronously even though `chineseText` itself hasn't changed.
    private var aiSegmentsToken: String {
        (aiSegments ?? []).map(\.text).joined(separator: "\u{1F}")
    }

    var body: some View {
        FlowLayout(spacing: 4) {
            ForEach(segments.filter { $0.isValidForDisplay }) { segment in
                if segment.isPunctuation {
                    // Display punctuation inline without ruby annotation
                    PunctuationView(text: segment.text)
                } else {
                    RubyWordView(segment: segment) {
                        onWordTap?(segment)
                    }
                }
            }
        }
        .onAppear {
            updateSegments()
        }
        .onChange(of: chineseText) { _, _ in
            updateSegments()
        }
        .onChange(of: aiSegmentsToken) { _, _ in
            updateSegments()
        }
    }

    private func updateSegments() {
        // Prefer AI-identified word boundaries when available; otherwise fall
        // back to local segmentation.
        if let aiSegments, !aiSegments.isEmpty {
            segments = aiSegments
        } else {
            let analyzed = ChineseTextAnalyzer.shared.segmentWithPartsOfSpeech(chineseText)
            segments = analyzed.map { RubySegment(from: $0) }
        }
    }
}

/// Inline punctuation display (no ruby annotation)
/// Aligns with the baseline of Chinese characters by adding a ghost line
/// matching wherever the pinyin row sits in regular RubyWordViews.
struct PunctuationView: View {
    let text: String

    @AppStorage("showPinyin") private var showPinyin: Bool = true
    @AppStorage("pinyinPosition") private var pinyinPosition: String = "above"

    var body: some View {
        VStack(spacing: 2) {
            if showPinyin && pinyinPosition == "above" {
                ghostPinyinLine
            }

            // Punctuation aligned with Chinese characters
            Text(text)
                .font(.title2)
                .fontWeight(.medium)
                .foregroundStyle(.primary)

            if showPinyin && pinyinPosition == "below" {
                ghostPinyinLine
            }
        }
        .padding(.vertical, 4)
    }

    /// Empty space matching the pinyin line height in RubyWordView.
    private var ghostPinyinLine: some View {
        Text(" ")
            .font(.caption)
            .opacity(0)
    }
}

/// Individual word with pinyin rendered around the character(s) according to
/// the user's Appearance settings (show/hide, above/below/inline, tone colors).
struct RubyWordView: View {
    let segment: RubySegment
    let action: () -> Void

    @State private var isHovered: Bool = false

    @AppStorage("showPinyin") private var showPinyin: Bool = true
    @AppStorage("pinyinPosition") private var pinyinPosition: String = "above"
    @AppStorage("toneColors") private var toneColors: Bool = true
    @State private var localization = LocalizationManager.shared

    /// The ruby line teaches a learner how to read the characters. A native
    /// Mandarin reader — who sees this view only when a Chinese passage turns
    /// up while they are studying English — already reads them, so annotating
    /// every word would be visual noise over their own language. The
    /// `showPinyin` preference still applies on top of this for the learner
    /// who does want it hidden.
    private var showsRuby: Bool {
        showPinyin && localization.learningIsChinese
    }

    var body: some View {
        Button(action: action) {
            wordLayout
                .padding(.horizontal, 6)
                .padding(.vertical, 4)
                .background(
                    RoundedRectangle(cornerRadius: 6)
                        .fill(isHovered ? Color.accentColor.opacity(0.1) : Color.clear)
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 6)
                        .stroke(segment.partOfSpeech.color.opacity(0.3), lineWidth: 1)
                )
        }
        .buttonStyle(.plain)
        .onHover { hovering in
            withAnimation(.easeInOut(duration: 0.15)) {
                isHovered = hovering
            }
        }
    }

    @ViewBuilder
    private var wordLayout: some View {
        if !showsRuby {
            characterText
        } else {
            switch pinyinPosition {
            case "below":
                VStack(spacing: 2) {
                    characterText
                    pinyinText
                }
            case "inline":
                HStack(alignment: .firstTextBaseline, spacing: 4) {
                    characterText
                    pinyinText
                }
            default:  // "above"
                VStack(spacing: 2) {
                    pinyinText
                    characterText
                }
            }
        }
    }

    /// Pinyin line. With tone colors enabled, each SYLLABLE gets its own tone
    /// color from the shared `PinyinConverter.Tone` palette — a multi-syllable
    /// word like 学习 shows xué in orange and xí in orange/green per syllable,
    /// instead of the whole word taking the first detected tone's color
    /// (which gave learners wrong tone feedback on every polysyllabic word).
    @ViewBuilder
    private var pinyinText: some View {
        Group {
            if toneColors {
                Text(PinyinConverter.coloredPinyin(fromPinyin: segment.pinyin))
            } else {
                Text(segment.pinyin)
                    .foregroundStyle(Color.secondary)
            }
        }
        .font(.caption)
        .lineLimit(1)
        .minimumScaleFactor(0.7)
    }

    private var characterText: some View {
        Text(segment.text)
            .font(.title2)
            .fontWeight(.medium)
            .foregroundStyle(.primary)
    }
}

/// Detailed popup view for a selected word
/// Fetches the actual translation of the word using Translation API
/// Always displays: Chinese word, pinyin, and English definition
/// Handles both Chinese and English input words
struct WordDetailPopover: View {
    let segment: RubySegment
    let contextTranslation: String  // Full sentence translation for context
    let onSave: (String) -> Void    // Pass the word definition when saving
    let onCopy: () -> Void
    let onDismiss: () -> Void

    @Environment(SavedTermsStore.self) private var savedTermsStore
    @State private var prefs = AppPreferences.shared
    @State private var showCopiedFeedback: Bool = false
    @State private var englishDefinition: String = ""
    @State private var chineseWord: String = ""
    @State private var pinyinText: String = ""
    @State private var isLoadingTranslation: Bool = true
    @State private var translationError: String?

    /// Check if the segment text contains Chinese characters
    private var segmentIsChinese: Bool {
        segment.text.contains { $0.isChineseCharacter }
    }

    /// The learning-language side leads (中文 UI → English headline, Chinese
    /// gloss, English narration first; English UI → Chinese headline with
    /// pinyin, English gloss, Mandarin narration first).
    private var learningChinese: Bool { LocalizationManager.shared.learningIsChinese }

    /// The learning-language text — what gets the headline, primary
    /// narration, and the plain Copy button.
    private var headlineWord: String { learningChinese ? chineseWord : englishDefinition }

    private var isSaved: Bool {
        savedTermsStore.contains(chinese: chineseWord.isEmpty ? segment.text : chineseWord)
    }

    var body: some View {
        VStack(spacing: 16) {
            // Large display — the learning-language side of the word
            VStack(spacing: 4) {
                if isLoadingTranslation {
                    ProgressView()
                        .controlSize(.small)
                    Text("Loading...")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                } else {
                    if learningChinese {
                        Text(pinyinText)
                            .font(.title3)
                            .foregroundStyle(.secondary)

                        Text(chineseWord)
                            .font(.system(size: 56, weight: .medium))
                    } else {
                        Text(englishDefinition)
                            .font(.system(size: 40, weight: .medium))
                            .lineLimit(2)
                            .minimumScaleFactor(0.4)
                            .multilineTextAlignment(.center)
                    }

                    // Part of speech badge
                    Text(segment.partOfSpeech.displayName)
                        .font(.caption)
                        .fontWeight(.semibold)
                        .foregroundStyle(.white)
                        .padding(.horizontal, 10)
                        .padding(.vertical, 3)
                        .background(
                            Capsule()
                                .fill(segment.partOfSpeech.color)
                        )
                }
            }

            Divider()

            // Definition section — the native-language gloss
            VStack(alignment: .leading, spacing: 8) {
                Text("Definition")
                    .font(.caption)
                    .fontWeight(.semibold)
                    .foregroundStyle(.secondary)

                if isLoadingTranslation {
                    HStack(spacing: 8) {
                        ProgressView()
                            .controlSize(.small)
                        Text("Translating...")
                            .font(.body)
                            .foregroundStyle(.secondary)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                } else if let error = translationError {
                    VStack(alignment: .leading, spacing: 4) {
                        Text(error)
                            .font(.caption)
                            .foregroundStyle(.red)

                        // Fallback to context if available
                        if !contextTranslation.isEmpty {
                            Text("Context: \(contextTranslation)")
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                } else {
                    Text(learningChinese ? englishDefinition : chineseWord)
                        .font(.body)
                        .fontWeight(.medium)
                        .frame(maxWidth: .infinity, alignment: .leading)
                }
            }
            .padding(.horizontal)

            Divider()

            // Action buttons — learning-language narration first
            HStack(spacing: 12) {
                if learningChinese {
                    Button {
                        SpeechService.speakChinese(chineseWord)
                    } label: {
                        Label("中文", systemImage: "speaker.wave.2")
                    }
                    .buttonStyle(.bordered)
                    .disabled(isLoadingTranslation || chineseWord.isEmpty)

                    // Native-language narration (dual narration).
                    if prefs.dualNarration {
                        Button {
                            SpeechService.speakEnglish(englishDefinition)
                        } label: {
                            Label("EN", systemImage: "speaker.wave.2")
                        }
                        .buttonStyle(.bordered)
                        .disabled(isLoadingTranslation || englishDefinition.isEmpty)
                    }
                } else {
                    Button {
                        SpeechService.speakEnglish(englishDefinition)
                    } label: {
                        Label("EN", systemImage: "speaker.wave.2")
                    }
                    .buttonStyle(.bordered)
                    .disabled(isLoadingTranslation || englishDefinition.isEmpty)

                    if prefs.dualNarration {
                        Button {
                            SpeechService.speakChinese(chineseWord)
                        } label: {
                            Label("中文", systemImage: "speaker.wave.2")
                        }
                        .buttonStyle(.bordered)
                        .disabled(isLoadingTranslation || chineseWord.isEmpty)
                    }
                }

                Button {
                    ClipboardService.copy(headlineWord)
                    showCopiedFeedback = true
                    onCopy()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                        showCopiedFeedback = false
                    }
                } label: {
                    Label(showCopiedFeedback ? "Copied!" : "Copy", systemImage: showCopiedFeedback ? "checkmark" : "doc.on.doc")
                }
                .buttonStyle(.bordered)
                .tint(showCopiedFeedback ? .green : nil)
                .disabled(isLoadingTranslation || headlineWord.isEmpty)

                Button {
                    // Pass the word-specific translation when saving
                    let definition = englishDefinition.isEmpty ? contextTranslation : englishDefinition
                    onSave(definition)
                } label: {
                    Label(isSaved ? "Saved" : "Save", systemImage: isSaved ? "bookmark.fill" : "bookmark")
                }
                .buttonStyle(.bordered)
                .tint(isSaved ? .green : nil)
                .disabled(isLoadingTranslation || isSaved)
            }

            // Copy-everything button (pinyin included only when the user is
            // learning Chinese — it is a learner aid, not native furniture)
            Button {
                let definition = englishDefinition.isEmpty ? contextTranslation : englishDefinition
                let fullText = learningChinese
                    ? "\(chineseWord) (\(pinyinText))\n\(definition)"
                    : "\(englishDefinition)\n\(chineseWord)"
                ClipboardService.copy(fullText)
                showCopiedFeedback = true
                DispatchQueue.main.asyncAfter(deadline: .now() + 1.5) {
                    showCopiedFeedback = false
                }
            } label: {
                Label(learningChinese ? "Copy with Pinyin" : "Copy All", systemImage: "doc.on.doc.fill")
                    .fitSingleLine()
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .disabled(isLoadingTranslation)
        }
        .padding()
        .frame(minWidth: 280)
        .task {
            await fetchWordDetails()
        }
    }

    /// Fetch the translation details for this word
    /// Always produces: Chinese word, pinyin, and English definition
    private func fetchWordDetails() async {
        isLoadingTranslation = true
        translationError = nil

        do {
            if segmentIsChinese {
                // Input is Chinese: use as-is for Chinese, translate to English for definition
                chineseWord = segment.text
                pinyinText = segment.pinyin

                // Prefer the AI-identified meaning (already contextual) so the
                // popover opens instantly without a second translation call.
                if let aiMeaning = segment.translation, !aiMeaning.isEmpty {
                    englishDefinition = aiMeaning
                } else {
                    let translation = try await WordTranslationService.shared.translateToEnglish(segment.text)
                    englishDefinition = translation
                }
            } else {
                // Input is English: translate to Chinese, get pinyin, use original as definition
                englishDefinition = segment.text

                let chineseTranslation = try await WordTranslationService.shared.translateToChinese(segment.text)
                chineseWord = chineseTranslation
                pinyinText = PinyinConverter.convert(chineseTranslation)
            }

            await MainActor.run {
                isLoadingTranslation = false
            }
        } catch {
            await MainActor.run {
                // If translation fails, use what we have
                translationError = "Could not translate word"
                if segmentIsChinese {
                    chineseWord = segment.text
                    pinyinText = segment.pinyin
                    englishDefinition = contextTranslation
                } else {
                    englishDefinition = segment.text
                    chineseWord = contextTranslation.isEmpty ? segment.text : contextTranslation
                    pinyinText = PinyinConverter.convert(chineseWord)
                }
                isLoadingTranslation = false
            }
            print("Word translation error for '\(segment.text)': \(error)")
        }
    }
}

// MARK: - Preview

#Preview {
    VStack(spacing: 20) {
        RubyTextView(
            chineseText: "你好世界",
            englishMeaning: "Hello World"
        ) { segment in
            print("Tapped: \(segment.text)")
        }

        RubyTextView(
            chineseText: "我喜欢学习中文",
            englishMeaning: "I like to study Chinese"
        )
    }
    .padding()
    .environment(SavedTermsStore.shared)
}

//
//  TranslateView.swift
//  SwiftMandarin
//
//  Created by Roger Lin on 2/11/26.
//

import SwiftUI
import Translation

/// Main translation view - full-screen optimized for iPhone
/// Features:
/// - Bidirectional translation (English ↔ Chinese)
/// - Interactive character analysis with word segmentation
/// - History integration
/// - Quick copy/speak actions
struct TranslateView: View {
    @Environment(TranslationHistoryStore.self) private var historyStore
    @Environment(SavedTermsStore.self) private var savedTermsStore

    // Use shared state for persistence across tab switches
    private var sharedState: TranslationState { TranslationState.shared }

    // Version-agnostic holder for the Apple Translation configuration so the
    // view can deploy to iOS 17 (where TranslationSession doesn't exist).
    @State private var translationConfiguration = TranslationConfigurationBox()

    // For word analysis popover - using sheet(item:) pattern to avoid race condition
    // When selectedSegment is set, the sheet automatically shows; when nil, it dismisses
    @State private var selectedSegment: RubySegment?

    // The English-side counterpart, used when the learner is a Mandarin
    // speaker studying English and the English pane is the tappable one.
    @State private var selectedEnglishWord: AnalyzedEnglishWord?

    // Settings
    @AppStorage("autoTranslate") private var autoTranslate: Bool = false
    @AppStorage("defaultDirection") private var defaultDirectionRawValue: String = TranslationDirection.persistedDefault.rawValue
    @AppStorage("translateOnPaste") private var translateOnPaste: Bool = true
    @AppStorage("copyTranslationAutomatically") private var copyTranslationAutomatically: Bool = false
    @AppStorage("saveToHistoryAutomatically") private var saveToHistoryAutomatically: Bool = true

    // Focus state for keyboard dismissal
    @FocusState private var isInputFocused: Bool
    @State private var pendingAutoTranslateTask: Task<Void, Never>?
    @State private var preserveSourceTextDuringProgrammaticUpdate: Bool = false

    // Debounced persistence of the in-progress draft, so an unfinished
    // translation survives an app relaunch (state only lives across tab
    // switches otherwise).
    @State private var draftSaveTask: Task<Void, Never>?
    private static let draftKey = "translationDraft"

    // State for additional translation when input language mismatches direction
    @State private var additionalTranslation: String = ""
    @State private var isLoadingAdditionalTranslation: Bool = false

    // State for AI translation
    @State private var aiTranslationTask: Task<Void, Never>?
    @State private var isAITranslating: Bool = false
    @State private var aiTranslationError: String?
    @State private var aiSettings = AIModelSettings.shared

    // Study notes that arrive in the same structured response as an AI
    // translation. Apple's on-device Translation API returns none, so that
    // path offers an explicit "Explain" action instead of paying for a second
    // model call the learner didn't ask for.
    @State private var translationNotes: AITranslationResult?
    @State private var notesSourceSnapshot: String = ""
    @State private var isFetchingNotes: Bool = false
    @State private var notesTask: Task<Void, Never>?
    @State private var notesError: String?

    // State for AI word/phrase identification (powers the tap-to-learn view
    // with proper word boundaries when a translation comes from an AI provider)
    @State private var aiSegments: [RubySegment] = []
    @State private var isIdentifyingWords: Bool = false
    @State private var wordIdentificationTask: Task<Void, Never>?
    @State private var wordIdGeneration: Int = 0

    // Track last detected direction to reset configuration when input language changes
    @State private var lastDetectedDirection: TranslationDirection?

    // State for live speech translation
    @State private var showLiveSpeechTranslation: Bool = false

    // Computed bindings to shared state
    private var sourceText: Binding<String> {
        Binding(
            get: { sharedState.sourceText },
            set: { sharedState.sourceText = $0 }
        )
    }

    private var translatedText: String {
        get { sharedState.translatedText }
    }

    private var direction: TranslationDirection {
        get { sharedState.direction }
    }

    private var isTranslating: Bool {
        get { sharedState.isTranslating }
    }

    private var translationError: String? {
        get { sharedState.translationError }
    }

    // Store translation context for word definitions
    private var translationContext: String {
        sharedState.direction == .englishToChinese ? sharedState.sourceText : sharedState.translatedText
    }

    private var activeChineseText: String {
        let candidate = detectedChineseText.trimmingCharacters(in: .whitespacesAndNewlines)
        return containsChinese(candidate) ? candidate : ""
    }

    private var activeEnglishText: String {
        detectedEnglishText.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var canSaveActiveTerm: Bool {
        !activeChineseText.isEmpty && !activeEnglishText.isEmpty
    }

    private var isActiveTermSaved: Bool {
        canSaveActiveTerm && savedTermsStore.contains(chinese: activeChineseText)
    }

    var body: some View {
        NavigationStack {
            GeometryReader { geometry in
                ScrollView {
                    VStack(spacing: 0) {
                        // Direction toggle
                        directionToggle
                            .padding(.horizontal)
                            .padding(.top, 8)

                        // Source input section
                        sourceInputSection
                            .frame(minHeight: geometry.size.height * 0.35)

                        // Divider with swap button
                        swapDivider

                        // Translation output section
                        translationOutputSection
                            .frame(minHeight: geometry.size.height * 0.35)

                        Spacer(minLength: 20)
                    }
                }
                .onTapGesture {
                    // Dismiss keyboard when tapping outside text editor
                    isInputFocused = false
                }
            }
            .task {
                restoreDraftIfNeeded()
                applyDefaultDirectionIfNeeded()
            }
            // Persist the draft (debounced) whenever any of its parts change.
            .onChange(of: sharedState.sourceText) { _, _ in scheduleDraftSave() }
            .onChange(of: sharedState.translatedText) { _, _ in scheduleDraftSave() }
            .onChange(of: sharedState.direction) { _, _ in scheduleDraftSave() }
            .navigationTitle("Translate")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .primaryAction) {
                    Button {
                        clearAll()
                    } label: {
                        Image(systemName: "trash")
                    }
                    .disabled(!sharedState.hasContent)
                }
            }
            .background {
                // Apple Translation runs on iOS 18+/macOS 15+; on iOS 17 the
                // translate actions route to the configured AI provider.
                if #available(iOS 18.0, macOS 15.0, *) {
                    TranslationTaskHost(box: translationConfiguration) { session in
                        await performTranslation(session: session)
                    }
                }
            }
            .sheet(isPresented: $showLiveSpeechTranslation) {
                LiveSpeechTranslationView(
                    translationDirection: sharedState.direction,
                    onUseTranscript: { transcript in
                        // Set the transcript as source text
                        sharedState.sourceText = transcript
                        // Trigger translation if auto-translate is off
                        if !autoTranslate {
                            triggerTranslation()
                        }
                    },
                    onUseTranslation: { transcript, translation in
                        // Show both sides so the source text stays in sync
                        // with what was actually spoken.
                        let transcriptIsChinese = transcript.contains { $0.isChineseCharacter }
                        let direction: TranslationDirection = transcriptIsChinese ? .chineseToEnglish : .englishToChinese
                        preserveCurrentTranslationDuringSourceUpdate {
                            sharedState.direction = direction
                            sharedState.sourceText = transcript
                            sharedState.translatedText = translation
                        }
                        // Spoken translations join history/stats like typed ones.
                        if transcript != translation {
                            handleCompletedTranslation(source: transcript, target: translation, direction: direction)
                        }
                        // Identify words in the Chinese side for the tap-to-learn view.
                        startWordIdentification(for: activeChineseText)
                    }
                )
                #if os(iOS)
                .presentationDetents([.large])
                .presentationDragIndicator(.visible)
                #else
                .frame(minWidth: 500, minHeight: 600)
                #endif
                .localizedSurface()
            }
        }
    }

