                }
            } label: {
                Label(learningChinese ? "Copy with Pinyin" : "Copy All", systemImage: "doc.on.doc.fill")
                    .fitSingleLine()
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .disabled(isLoadingTranslation)
        }
        .padding()
        .frame(minWidth: 280)
        .task {
            await fetchWordDetails()
        }
